tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dgtts2, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 22', function test( t ) {
	t.strictEqual( dgtts2.length, 22, 'returns expected value' );
	t.end();
});

tape( 'the function returns the input array unchanged if N is zero', function test( t ) {
	var IPIV;
	var data;
	var DU2;
	var DU;
	var DL;
	var D;
	var B;
	var X;

	data = ROW_MAJOR_NO_TRANS_NRHS_GT_ONE;

	DL = new Float64Array( data.DL );
	D = new Float64Array( data.D );
	DU = new Float64Array( data.DU );
	DU2 = new Float64Array( data.DU2 );
	IPIV = new Int32Array( data.IPIV );
	B = new Float64Array( data.B );

	X = dgtts2( data.itrans, data.N, data.nrhs, DL, data.sdl, data.odl, D, data.sd, data.od, DU, data.sdu, data.odu, DU2, data.sdu2, data.odu2, IPIV, data.si, data.oi, B, data.sb1, data.sb2, data.ob );
	t.deepEqual( B, X, 'returns expected value' );

	t.end();
});

